// Unit tests for preprocessTranscript, preprocessTranscriptWithOptions, preprocessBatchWithKnowledge
import { describe, it, expect } from "vitest";
import {
  preprocessTranscript,
  preprocessTranscriptWithOptions,
} from "../../transcript/advanced-preprocessor.js";
import { preprocessBatchWithKnowledge } from "../../transcript/knowledge-preprocessor.js";

const GARDENING_TEXT =
  "Today we're planting lavender and roses in the garden. " +
  "I'll show you the best trowel and pruning shears for the job. " +
  "The Heuchera and Salvia look beautiful this time of year.";

describe("preprocessTranscript", () => {
  it("returns a PreprocessingResult with required fields", async () => {
    const result = await preprocessTranscript(GARDENING_TEXT, "vid123");
    expect(result.originalText).toBe(GARDENING_TEXT);
    expect(result.processedText).toBeDefined();
    expect(typeof result.processedText).toBe("string");
    expect(result.stages).toBeInstanceOf(Array);
    expect(result.stages.length).toBeGreaterThan(0);
    expect(result.metadata).toBeDefined();
  });

  it("populates metadata processingTime and botanicalTermsFound", async () => {
    const result = await preprocessTranscript(GARDENING_TEXT);
    expect(result.metadata.processingTime).toBeGreaterThanOrEqual(0);
    expect(result.metadata.botanicalTermsFound).toBeInstanceOf(Array);
  });

  it("handles empty transcript without throwing", async () => {
    const result = await preprocessTranscript("");
    expect(result.originalText).toBe("");
    expect(result.processedText).toBe("");
    expect(result.originalLength).toBe(0);
    expect(result.stages).toBeInstanceOf(Array);
  });

  it("reduces length for a long transcript", async () => {
    // Use >10 000 chars so Stage 6 maxLength cap (8000) is guaranteed to fire
    const longText = GARDENING_TEXT.repeat(65); // ~11 310 chars
    const result = await preprocessTranscript(longText);
    expect(result.processedLength).toBeLessThan(result.originalLength);
    expect(result.reductionPercentage).toBeGreaterThan(0);
  });
});

describe("preprocessTranscriptWithOptions", () => {
  it("respects maxLength option", async () => {
    // Stage 6 appends "..." (3 chars) when truncating, so maxLength: 97 → output ≤ 100
    const result = await preprocessTranscriptWithOptions(
      GARDENING_TEXT.repeat(50),
      { maxLength: 97 },
    );
    expect(result.processedText.length).toBeLessThanOrEqual(100);
  });

  it("works with enableAggressiveFiltering=false", async () => {
    // With aggressive filtering disabled Stage 3 entity culling is skipped;
    // short texts can expand slightly due to sentence-boundary normalisation in Stage 2.
    const result = await preprocessTranscriptWithOptions(GARDENING_TEXT, {
      enableAggressiveFiltering: false,
    });
    expect(result.stages).toBeInstanceOf(Array);
    expect(result.processedText).toBeDefined();
    expect(typeof result.processedLength).toBe("number");
  });
});

describe("preprocessBatchWithKnowledge", () => {
  it("returns empty Map for empty input array", async () => {
    const result = await preprocessBatchWithKnowledge([]);
    expect(result.size).toBe(0);
  });

  it("returns a Map with one entry per input transcript", async () => {
    const input = [
      { id: "v1", text: GARDENING_TEXT },
      { id: "v2", text: "hello world" },
    ];
    const result = await preprocessBatchWithKnowledge(input);
    expect(result.size).toBe(2);
    expect(result.has("v1")).toBe(true);
    expect(result.has("v2")).toBe(true);
  });

  it("each entry has processedText and knowledgeSources", async () => {
    const result = await preprocessBatchWithKnowledge([
      { id: "v1", text: GARDENING_TEXT },
    ]);
    const r = result.get("v1");
    expect(r).toBeDefined();
    expect(typeof r!.processedText).toBe("string");
    expect(r!.knowledgeSources).toBeDefined();
    expect(typeof r!.knowledgeSources.plantDictionary).toBe("boolean");
  });
});

/**
 * Unit tests for APIBudgetManager.
 *
 * Tests budget enforcement, usage tracking, and emergency stop —
 * critical for cost control in production.
 */

import { describe, it, expect, beforeEach } from "vitest";
import { APIBudgetManager, createBudgetManager } from "../../ai/api-budget-manager.js";

describe("APIBudgetManager", () => {
  let manager: APIBudgetManager;

  beforeEach(() => {
    manager = new APIBudgetManager({
      openaiDailyBudget: 0.50,
      openaiMonthlyBudget: 10.00,
      openaiPerRequestLimit: 0.01,
      openaiAlertThreshold: 0.80,
      externalAPIDailyQuota: 100,
      externalAPIRateLimit: 10,
      emergencyStopEnabled: true,
    });
  });

  it("allows a request within budget", () => {
    expect(manager.canUseOpenAI(0.003).allowed).toBe(true);
  });

  it("rejects request exceeding per-request limit", () => {
    const result = manager.canUseOpenAI(0.02);
    expect(result.allowed).toBe(false);
    expect(result.reason).toMatch(/per-request limit/);
  });

  it("rejects request that would exceed daily budget", () => {
    manager.trackOpenAIUsage(0.498, 1000, "gpt-4o-mini");
    const result = manager.canUseOpenAI(0.005); // 0.503 > 0.50
    expect(result.allowed).toBe(false);
    expect(result.reason).toMatch(/[Dd]aily budget/);
  });

  it("tracks usage counters and accumulated cost", () => {
    manager.trackOpenAIUsage(0.001, 200, "gpt-4o-mini");
    manager.trackOpenAIUsage(0.002, 400, "gpt-4o-mini");
    const stats = manager.getAllUsageStats().find((s) => s.service === "openai");
    expect(stats?.requestsToday).toBe(2);
    expect(stats?.costToday).toBeCloseTo(0.003, 5);
  });

  it("does not emergency-stop on fresh instance", () => {
    expect(manager.shouldEmergencyStop().stop).toBe(false);
  });

  it("triggers emergency stop when daily budget is exceeded", () => {
    manager.trackOpenAIUsage(0.51, 50000, "gpt-4o-mini");
    const result = manager.shouldEmergencyStop();
    expect(result.stop).toBe(true);
    expect(result.reason).toMatch(/[Dd]aily budget/);
  });

  it("respects emergencyStopEnabled: false", () => {
    const noStop = new APIBudgetManager({ openaiDailyBudget: 0.10, emergencyStopEnabled: false });
    noStop.trackOpenAIUsage(0.50, 10000, "gpt-4o-mini");
    expect(noStop.shouldEmergencyStop().stop).toBe(false);
  });

  it("estimates cost — positive and scales with length", () => {
    const shortCost = manager.estimateOpenAICost("short");
    const longCost = manager.estimateOpenAICost("a".repeat(10000));
    expect(shortCost).toBeGreaterThan(0);
    expect(longCost).toBeGreaterThan(shortCost);
  });

  it("canUseExternalAPI allows initially and rejects on quota exhaustion", () => {
    expect(manager.canUseExternalAPI("awin").allowed).toBe(true);
    for (let i = 0; i < 100; i++) manager.trackExternalAPIUsage("awin");
    expect(manager.canUseExternalAPI("awin").allowed).toBe(false);
  });

  it("resetAll clears counters and allows fresh usage", () => {
    manager.trackOpenAIUsage(0.49, 100000, "gpt-4o-mini");
    manager.resetAll();
    expect(manager.getAllUsageStats().length).toBe(0);
    expect(manager.canUseOpenAI(0.005).allowed).toBe(true);
  });

  it("createBudgetManager factory respects config overrides", () => {
    const m = createBudgetManager({ openaiPerRequestLimit: 0.001 });
    expect(m).toBeInstanceOf(APIBudgetManager);
    expect(m.canUseOpenAI(0.002).allowed).toBe(false);
  });
});

/**
 * Unit tests for PaymentMiddleware (x402-middleware.ts).
 * Covers in-memory paths only — no network calls required.
 */

import { describe, it, expect } from "vitest";
import {
  PaymentMiddleware,
  DEFAULT_TOOL_PRICING,
} from "../../x402-middleware.js";

const BASE_CONFIG = {
  enabled: true,
  walletAddress: "0xtest",
  freeTierDailyLimit: 3,
  pricing: {},
  apiKeys: ["valid-key-abc"],
};

describe("PaymentMiddleware", () => {
  describe("disabled mode", () => {
    it("authorizes all requests when enabled=false", async () => {
      const mw = new PaymentMiddleware({ ...BASE_CONFIG, enabled: false });
      const result = await mw.authorize({ toolName: "analyze_video" });
      expect(result.authorized).toBe(true);
      expect((result as { method: string }).method).toBe("disabled");
    });
  });

  describe("API key auth", () => {
    it("authorizes valid API key", async () => {
      const mw = new PaymentMiddleware(BASE_CONFIG);
      const result = await mw.authorize({ toolName: "analyze_video", apiKey: "valid-key-abc" });
      expect(result.authorized).toBe(true);
      expect((result as { method: string }).method).toBe("api_key");
    });

    it("falls through to free tier on invalid API key", async () => {
      const mw = new PaymentMiddleware(BASE_CONFIG);
      const result = await mw.authorize({ toolName: "analyze_video", apiKey: "wrong-key" });
      expect(result.authorized).toBe(true);
      expect((result as { method: string }).method).toBe("free_tier");
    });
  });

  describe("free tier", () => {
    it("grants full quota to fresh agent", () => {
      const mw = new PaymentMiddleware(BASE_CONFIG);
      expect(mw.getFreeTierRemaining("agent-1")).toBe(3);
    });

    it("depletes quota on each authorized call", async () => {
      const mw = new PaymentMiddleware(BASE_CONFIG);
      await mw.authorize({ toolName: "discover_opportunities", agentId: "agent-x" });
      await mw.authorize({ toolName: "discover_opportunities", agentId: "agent-x" });
      expect(mw.getFreeTierRemaining("agent-x")).toBe(1);
    });

    it("returns unauthorized with requiredPayment after exhaustion", async () => {
      const mw = new PaymentMiddleware({ ...BASE_CONFIG, freeTierDailyLimit: 1 });
      await mw.authorize({ toolName: "analyze_video", agentId: "agent-z" });
      const result = await mw.authorize({ toolName: "analyze_video", agentId: "agent-z" });
      expect(result.authorized).toBe(false);
      expect((result as { requiredPayment?: unknown }).requiredPayment).toBeDefined();
    });
  });

  describe("getToolPrice", () => {
    it("returns default pricing for analyze_video", () => {
      const mw = new PaymentMiddleware(BASE_CONFIG);
      expect(mw.getToolPrice("analyze_video")).toBe(DEFAULT_TOOL_PRICING["analyze_video"]);
    });

    it("returns deep pricing for analyze_video:deep", () => {
      const mw = new PaymentMiddleware(BASE_CONFIG);
      const price = mw.getToolPrice("analyze_video", { analysis_depth: "deep" });
      expect(price).toBe(DEFAULT_TOOL_PRICING["analyze_video:deep"]);
    });

    it("multiplies per-video for batch_analyze", () => {
      const mw = new PaymentMiddleware(BASE_CONFIG);
      const price = mw.getToolPrice("batch_analyze", { youtube_urls: ["a", "b", "c"] });
      expect(price).toBeCloseTo(DEFAULT_TOOL_PRICING["batch_analyze"]! * 3);
    });
  });

  describe("getReceiptStats", () => {
    it("aggregates receipt counts and method breakdown", async () => {
      const mw = new PaymentMiddleware({ ...BASE_CONFIG, freeTierDailyLimit: 5 });
      await mw.authorize({ toolName: "analyze_video", agentId: "stat-agent" });
      await mw.authorize({ toolName: "get_seasonal_calendar", agentId: "stat-agent" });
      const stats = mw.getReceiptStats();
      expect(stats.totalReceipts).toBe(2);
      expect(stats.byMethod["free_tier"]).toBe(2);
      expect(stats.byTool["analyze_video"]?.count).toBe(1);
    });
  });
});

/**
 * Integration tests for x402 payment flow.
 *
 * Tests the PaymentMiddleware lifecycle:
 * - Disabled mode (all requests pass)
 * - API key authentication
 * - Free tier quota management
 * - x402 payment header decode + verification
 * - Receipt tracking and statistics
 * - Pricing resolution for different tools/depths
 *
 * Does NOT call the actual Coinbase facilitator.
 * x402 facilitator verification tests are marked with describe.skip.
 */

import { describe, it, expect, beforeEach } from "vitest";
import {
  PaymentMiddleware,
  createPaymentMiddleware,
  DEFAULT_TOOL_PRICING,
  type PaymentConfig,
  type RequestContext,
} from "../../x402-middleware.js";

describe("Payment Flow Integration", () => {
  describe("Disabled mode", () => {
    let middleware: PaymentMiddleware;

    beforeEach(() => {
      middleware = createPaymentMiddleware({ enabled: false });
    });

    it("authorizes all requests when payments disabled", async () => {
      const result = await middleware.authorize({
        toolName: "analyze_video",
        agentId: "test-agent",
      });

      expect(result.authorized).toBe(true);
      if (result.authorized) {
        expect(result.method).toBe("disabled");
        expect(result.receipt).toBeDefined();
        expect(result.receipt!.amount).toBe(0);
      }
    });

    it("creates receipts even when disabled", async () => {
      await middleware.authorize({
        toolName: "analyze_video",
        agentId: "test-agent",
      });

      const receipts = middleware.getReceipts();
      // Disabled mode creates a receipt but does not log it via logReceipt
      // The receipt is returned in the result but not stored internally
      // (this is the actual behavior of the middleware)
      expect(receipts.length).toBe(0);
    });
  });

  describe("API key authentication", () => {
    let middleware: PaymentMiddleware;

    beforeEach(() => {
      middleware = new PaymentMiddleware({
        enabled: true,
        freeTierDailyLimit: 0,
        pricing: { ...DEFAULT_TOOL_PRICING },
        apiKeys: ["valid-key-123", "valid-key-456"],
      });
    });

    it("authorizes with valid API key", async () => {
      const result = await middleware.authorize({
        toolName: "analyze_video",
        agentId: "agent-1",
        apiKey: "valid-key-123",
      });

      expect(result.authorized).toBe(true);
      if (result.authorized) {
        expect(result.method).toBe("api_key");
        expect(result.receipt).toBeDefined();
        expect(result.receipt!.method).toBe("api_key");
      }
    });

    it("rejects invalid API key and falls through to 402", async () => {
      const result = await middleware.authorize({
        toolName: "analyze_video",
        agentId: "agent-1",
        apiKey: "invalid-key",
      });

      expect(result.authorized).toBe(false);
      if (!result.authorized) {
        expect(result.requiredPayment).toBeDefined();
        expect(result.requiredPayment!.x402Version).toBe(2);
      }
    });

    it("logs receipts for API key auth", async () => {
      await middleware.authorize({
        toolName: "analyze_video",
