/**
 * AI-Powered Objective Extraction
 *
 * Uses GPT-4o-mini to extract learning objectives from teaching sections.
 *
 * Cost Analysis:
 * - GPT-4o-mini: $0.150 per 1M input tokens, $0.600 per 1M output tokens
 * - Avg section: 300 words = ~400 tokens input
 * - Expected output: ~50 tokens (3-5 objectives)
 * - Cost per section: ~$0.0001 (0.01c)
 * - Total for 100 sections: ~$0.01
 *
 * Ported from monolith lib/services/ai-objective-extraction.ts.
 * Standalone: uses OpenAI SDK directly, no Prisma or monolith dependencies.
 */

import OpenAI from "openai";
import type { Logger } from "../types.js";
import { defaultLogger } from "../types.js";

// ============================================================================
// TYPES
// ============================================================================

export interface AIObjectiveResult {
  objectives: string[];
  confidence: number; // 0-1
  reasoning: string;
  tokenUsage: {
    input: number;
    output: number;
    cost: number;
  };
}

export interface ObjectiveExtractionOptions {
  apiKey: string;
  model?: string;
  logger?: Logger;
}

// ============================================================================
// EXTRACTION FUNCTIONS
// ============================================================================

/**
 * Extract learning objectives using AI.
 *
 * Returns 3-5 specific, actionable learning objectives from a teaching section.
 * Each objective focuses on practical skills, not just knowledge.
 *
 * @param sectionText - Teaching section text
 * @param videoTitle - Video title for context
 * @param keyConcepts - Key concepts extracted from section
 * @param options - API key and optional settings
 * @returns AI-extracted objectives with confidence and cost
 */
export async function extractObjectivesWithAI(
  sectionText: string,
  videoTitle: string,
  keyConcepts: string[],
  options: ObjectiveExtractionOptions,
): Promise<AIObjectiveResult> {
  const logger = options.logger ?? defaultLogger;
  const model = options.model ?? "gpt-4o-mini";

  const openai = new OpenAI({ apiKey: options.apiKey });

  const prompt = `You are analyzing a teaching section from a gardening video titled "${videoTitle}".

Extract 3-5 specific, actionable learning objectives that a viewer will be able to do after watching this section.

Key concepts mentioned: ${keyConcepts.join(", ")}

Section transcript:
${sectionText.substring(0, 1500)}

Requirements:
1. Each objective should be specific and actionable (e.g., "Identify signs of overwatering in tomato plants")
2. Focus on practical skills, not just knowledge (prefer "do X" over "understand X")
3. Use the key concepts if relevant
4. Keep each objective concise (max 10 words)
5. Return ONLY the objectives as a JSON array, nothing else

Example output:
{
  "objectives": [
    "Prune rose bushes to encourage new growth",
    "Identify the optimal time for spring pruning",
    "Select the right pruning tools for different stems"
  ],
  "confidence": 0.9,
  "reasoning": "Clear step-by-step demonstration with visual cues"
}`;

  try {
    const response = await openai.chat.completions.create({
      model,
      messages: [
        {
          role: "system",
          content:
            "You are an expert at analyzing educational content and extracting learning objectives. Return only valid JSON.",
        },
        {
          role: "user",
          content: prompt,
        },
      ],
      temperature: 0.3,
      max_tokens: 200,
      response_format: { type: "json_object" },
    });

    const content = response.choices[0]?.message?.content;
    if (!content) {
      throw new Error("Empty response from OpenAI");
    }

    const parsed = JSON.parse(content);

    // Validate response structure
    if (!Array.isArray(parsed.objectives)) {
      throw new Error("Invalid response format: objectives must be an array");
    }

    // Calculate cost
    const inputTokens = response.usage?.prompt_tokens || 0;
    const outputTokens = response.usage?.completion_tokens || 0;
    const inputCost = (inputTokens / 1_000_000) * 0.15; // $0.150 per 1M tokens
    const outputCost = (outputTokens / 1_000_000) * 0.6; // $0.600 per 1M tokens
    const totalCost = inputCost + outputCost;

    return {
      objectives: parsed.objectives.slice(0, 5), // Max 5 objectives
      confidence: parsed.confidence || 0.8,
      reasoning: parsed.reasoning || "AI-extracted objectives",
      tokenUsage: {
        input: inputTokens,
        output: outputTokens,
        cost: totalCost,
      },
    };
  } catch (error: unknown) {
    const message =
      error instanceof Error ? error.message : "Unknown error";
    logger.error(
      "AI objective extraction failed",
      error instanceof Error ? error : undefined,
      { message },
    );
    return {
      objectives: [],
      confidence: 0,
      reasoning: `Error: ${message}`,
      tokenUsage: {
        input: 0,
        output: 0,
        cost: 0,
      },
    };
  }
}

/**
 * Batch extract objectives for multiple sections.
 *
 * Processes sections sequentially to avoid rate limits.
 * Includes budget monitoring to prevent cost overruns.
 *
 * @param sections - Array of sections to process
 * @param options - API key and optional settings
 * @param maxBudget - Maximum budget in USD (default: 0.10 for 100 sections)
 * @returns Results for all sections with total cost
 */
export async function batchExtractObjectives(
  sections: Array<{
    id: string;
    text: string;
    videoTitle: string;
    keyConcepts: string[];
  }>,
  options: ObjectiveExtractionOptions,
  maxBudget: number = 0.1,
): Promise<{
  results: Array<AIObjectiveResult & { sectionId: string }>;
  totalCost: number;
  processed: number;
  failed: number;
}> {
  const logger = options.logger ?? defaultLogger;
  const results: Array<AIObjectiveResult & { sectionId: string }> = [];
  let totalCost = 0;
  let processed = 0;
  let failed = 0;

  logger.info("AI Objective Extraction starting", {
    maxBudget,
    sectionCount: sections.length,
  });

  for (let i = 0; i < sections.length; i++) {
    const section = sections[i]!;

    // Check budget before processing
    if (totalCost >= maxBudget) {
      logger.warn("Budget limit reached, stopping extraction", {
        maxBudget,
        totalCost,
      });
      break;
    }

    logger.info("Processing section", {
      index: i + 1,
      total: sections.length,
      sectionId: section.id.substring(0, 20),
    });

    try {
      const result = await extractObjectivesWithAI(
        section.text,
        section.videoTitle,
        section.keyConcepts,
        options,
      );

      totalCost += result.tokenUsage.cost;
      processed++;

      if (result.objectives.length > 0) {
        logger.info("Extracted objectives", {
          count: result.objectives.length,
          cost: result.tokenUsage.cost,
          sampleObjectives: result.objectives.slice(0, 2),
        });
      } else {
        logger.warn("Failed to extract objectives", {
          reasoning: result.reasoning,
        });
        failed++;
      }

      results.push({
        ...result,
        sectionId: section.id,
      });

      // Rate limiting: Wait 100ms between requests
      await new Promise((resolve) => setTimeout(resolve, 100));
    } catch (error: unknown) {
      const message =
        error instanceof Error ? error.message : "Unknown error";
      logger.error(
        "Section extraction error",
        error instanceof Error ? error : undefined,
        { sectionId: section.id },
      );
      failed++;
      results.push({
        sectionId: section.id,
        objectives: [],
        confidence: 0,
        reasoning: `Error: ${message}`,
        tokenUsage: {
          input: 0,
          output: 0,
          cost: 0,
        },
      });
    }
  }

  logger.info("Batch extraction summary", {
    totalSections: sections.length,
    processed,
    successful: processed - failed,
    successRate:
      processed > 0 ? ((processed - failed) / processed) * 100 : 0,
    failed,
    totalCost,
    avgCostPerSection: processed > 0 ? totalCost / processed : 0,
  });

  return {
    results,
    totalCost,
    processed,
    failed,
  };
}

/**
 * Get top N sections by quality score for AI extraction.
 *
 * Strategy: Focus AI budget on high-quality sections that will be featured.
 *
 * @param sections - All detected sections with quality scores
 * @param topN - Number of top sections to extract (default: 100)
 * @returns Top N sections sorted by quality
 */
export function selectTopSectionsForAI(
  sections: Array<{
    id: string;
    text: string;
    videoTitle: string;
    keyConcepts: string[];
    qualityScore: number;
  }>,
  topN: number = 100,
): Array<{
  id: string;
  text: string;
  videoTitle: string;
  keyConcepts: string[];
}> {
  return sections
    .sort((a, b) => b.qualityScore - a.qualityScore)
    .slice(0, topN)
    .map((s) => ({
      id: s.id,
      text: s.text,
      videoTitle: s.videoTitle,
      keyConcepts: s.keyConcepts,
    }));
}

/**
 * Skill Extraction Service
 *
 * Analyzes video transcripts to:
 * 1. Identify skills being taught (e.g., "rose_pruning", "propagation")
 * 2. Determine skill level (beginner, intermediate, advanced, expert)
 * 3. Assess teaching quality and coverage
 * 4. Extract timestamps for skill-focused segments
 * 5. Reformulate titles for high-intent search queries
 * 6. Position video in learning sequence
 *
 * Ported from monolith lib/services/skill-extraction-service.ts.
 * Standalone: uses OpenAI SDK directly, no Prisma or monolith dependencies.
 * The database-save functions (saveVideoSkills, processVideoForSkills, etc.)
 * are intentionally omitted -- the MCP consumer handles persistence.
 */

import OpenAI from "openai";
import type { Logger } from "../types.js";
import { defaultLogger } from "../types.js";

// ============================================================================
// TYPES
// ============================================================================

/**
 * Skill Analysis Result
 *
 * OPTIMIZATION: Removed unused engagement features (saves 33% cost)
 * Previous cost: $0.003/video -> New cost: $0.002/video
 */
export interface SkillAnalysis {
  // Primary skill taught
  primarySkill: {
    name: string; // "rose_pruning"
    displayName: string; // "Rose Pruning"
    category: string; // "plant_species" | "technique" | "seasonal_task" | "garden_style"
    skillLevel: string; // "beginner" | "intermediate" | "advanced" | "expert"
    coveragePercent: number; // 0-100
  };

  // Additional skills covered
  secondarySkills: Array<{
    name: string;
    displayName: string;
    category: string;
    skillLevel: string;
    coveragePercent: number;
  }>;

  // Teaching quality metrics
  quality: {
    explanationQuality: number; // 0-100: How well explained?
    visualQuality: number; // 0-100: Visual demonstrations
    practicalValue: number; // 0-100: Actionable takeaways
    overallScore: number; // 0-100: Combined quality
  };

  // Video intent
  intent: {
    type:
      | "how_to"
      | "explainer"
      | "demonstration"
      | "tips"
      | "troubleshooting"
      | "review"
      | "showcase";
    confidence: number; // 0-100
    reformulatedTitle: string; // High-intent version
  };

  // Sequence positioning
  sequencing: {
    position:
      | "foundational"
      | "beginner"
      | "intermediate"
      | "advanced"
      | "expert"
      | "specialized";
    prerequisiteSkills: string[]; // Skills needed before this
    nextSkillSuggestions: string[]; // Skills to learn next
  };

  // Timestamps for skill-focused segments
  timestamps: Array<{
    skill: string;
    start: string; // "00:02:14"
    end: string; // "00:05:30"
    context: string; // What's happening in this segment
  }>;
}

/**
 * Action Intent Signal (for selective injection)
 */
export interface ActionIntentSignal {
  timestamp: string;
  keyword: string;
  label: string;
  intentScore: number;
  intentStrength: "low" | "medium" | "high";
  category: string;
}

/**
 * Options for skill extraction.
 */
export interface SkillExtractionOptions {
  apiKey: string;
  model?: string;
  logger?: Logger;
}

// ============================================================================
// SKILL EXTRACTION
// ============================================================================

/**
 * Extract skills from a video transcript using AI.
 *
 * Supports optional action intent signals for improved accuracy.
 * Returns structured skill analysis with quality metrics and sequencing.
 *
 * @param transcript - Full transcript text
 * @param videoTitle - Title of the video
 * @param options - API key and optional settings
 * @param videoDescription - Optional video description for context
 * @param detectedActions - Optional action signals from preprocessing
 * @returns Structured skill analysis
 */
export async function extractVideoSkills(
  transcript: string,
  videoTitle: string,
  options: SkillExtractionOptions,
  videoDescription?: string,
  detectedActions?: ActionIntentSignal[],
): Promise<SkillAnalysis> {
  const logger = options.logger ?? defaultLogger;
  const model = options.model ?? "gpt-4o-mini";

  logger.info("Analyzing video for skills", { videoTitle });

  const openai = new OpenAI({ apiKey: options.apiKey });

  // SELECTIVE ACTION INJECTION
  // Only inject high-confidence garden task actions
  const highIntentActions = detectedActions
    ?.filter(
      (action) =>
        action.category === "garden_task" &&
        action.intentStrength === "high" &&
        action.intentScore >= 7,
    )
    .slice(0, 6); // Max 6 actions to avoid token bloat

  // Build action context only if high-quality actions exist
  const actionContext =
    highIntentActions && highIntentActions.length > 0
      ? `

DETECTED TEACHING MOMENTS (high-confidence action intents):
${highIntentActions.map((a) => `- [${a.timestamp}] ${a.label} (intent score: ${a.intentScore})`).join("\n")}

IMPORTANT: These action intents indicate WHERE and WHAT is actively being TAUGHT (not just mentioned).
Use these as strong signals for:
- Primary/secondary skill identification (prioritize skills matching these actions)
- Coverage percentage estimation (use timestamps to calculate)
- Timestamp accuracy (align skill timestamps with action timestamps)
- Teaching quality assessment (high-intent actions = better teaching)
`
      : "";

  const prompt = `You are an expert at analyzing educational gardening videos to identify skills and assess teaching quality.

VIDEO TITLE: ${videoTitle}
${videoDescription ? `DESCRIPTION: ${videoDescription}\n` : ""}

TRANSCRIPT:
${transcript.slice(0, 15000)} ${transcript.length > 15000 ? "...(truncated)" : ""}${actionContext}

TASK: Analyze this video and extract:

1. PRIMARY SKILL: The main skill being taught
   - Skill name (snake_case): e.g., "rose_pruning", "seed_starting", "composting"
   - Display name: e.g., "Rose Pruning"
   - Category: "plant_species", "technique", "garden_style", "seasonal_task"
   - Skill level: "beginner", "intermediate", "advanced", "expert"
   - Coverage percent: How much of the video focuses on this skill? (0-100)

2. SECONDARY SKILLS: Other skills mentioned (max 3)
   - Same structure as primary skill

3. TEACHING QUALITY (0-100 for each):
   - Explanation quality: How clearly are concepts explained?
   - Visual quality: Are there good visual demonstrations?
   - Practical value: Are there actionable takeaways?
   - Overall score: Combined quality assessment

4. VIDEO INTENT:
   - Type: "how_to" (step-by-step), "explainer" (concepts), "demonstration" (showing),
           "tips" (quick advice), "troubleshooting" (solving problems), "review" (comparing/evaluating),
           "showcase" (tour/display)
   - Confidence: How confident are you in this classification? (0-100)
   - Reformulated title: Rewrite the title as a high-intent search query (e.g., "How to Prune Roses in Spring")
     Use phrases like: "How to...", "Guide to...", "Learn...", "Master...", "Complete Guide..."

5. SEQUENCE POSITION:
   - Position: "foundational" (absolute basics), "beginner" (first real project),
               "intermediate" (building on basics), "advanced" (complex techniques),
               "expert" (mastery level), "specialized" (niche topic)
   - Prerequisites: What skills should learner have first? (max 3, use empty array if none)
   - Next steps: What skills naturally follow this? (max 3, use empty array if none)

6. TIMESTAMPS: Key segments where skills are taught (max 5)
   - Skill name, start time (HH:MM:SS), end time (HH:MM:SS), brief context

Return as JSON:
{
  "primarySkill": {
    "name": "string",
    "displayName": "string",
    "category": "string",
    "skillLevel": "string",
    "coveragePercent": number
  },
  "secondarySkills": [
    {
      "name": "string",
      "displayName": "string",
      "category": "string",
      "skillLevel": "string",
      "coveragePercent": number
    }
  ],
  "quality": {
    "explanationQuality": number,
    "visualQuality": number,
    "practicalValue": number,
    "overallScore": number
  },
  "intent": {
    "type": "string",
    "confidence": number,
    "reformulatedTitle": "string"
  },
  "sequencing": {
    "position": "string",
    "prerequisiteSkills": ["string"],
    "nextSkillSuggestions": ["string"]
  },
  "timestamps": [
    {
      "skill": "string",
      "start": "00:00:00",
      "end": "00:00:00",
      "context": "string"
    }
  ]
}`;

  try {
    const response = await openai.chat.completions.create({
      model,
      messages: [
        {
          role: "system",
          content:
            "You are an expert educational content analyst specializing in gardening and horticulture. Return only valid JSON.",
        },
        {
          role: "user",
          content: prompt,
        },
      ],
      temperature: 0.3,
      response_format: { type: "json_object" },
    });

    const choice = response.choices[0];
    if (!choice) {
      throw new Error("No response choice from OpenAI");
    }
    const content = choice.message.content;
    if (!content) {
      throw new Error("Empty response from OpenAI");
    }

    const analysis: SkillAnalysis = JSON.parse(content);

    logger.info("Skill extraction result", {
      primarySkill: analysis.primarySkill.displayName,
      skillLevel: analysis.primarySkill.skillLevel,
      qualityScore: analysis.quality.overallScore,
      intentType: analysis.intent.type,
      reformulatedTitle: analysis.intent.reformulatedTitle,
    });

    return analysis;
  } catch (error) {
    logger.error(
      "Skill extraction failed",
      error instanceof Error ? error : undefined,
      { videoTitle },
    );
    throw error;
  }
}

/**
 * API Budget Manager
 *
 * Centralized rate limiting and budget tracking for external API usage.
 * Ensures per-request cost caps are enforced so analysis stays cheap.
 *
 * Ported from monolith lib/services/api-budget-manager.ts.
 * Standalone: no Prisma, no monolith dependencies. In-memory tracking
 * with optional persistence callbacks.
 *
 * Key features:
 * - Token bucket algorithm for rate limiting
 * - Daily/monthly budget tracking (in-memory, reset on restart)
 * - Cost estimation before API calls
 * - Emergency stop when budget exceeded
 * - Alert at configurable threshold (default 80%)
 * - Per-service usage tracking
 *
 * Usage:
 * ```typescript
 * import { APIBudgetManager, createBudgetManager } from 'video-commerce-mcp';
 *
 * const manager = createBudgetManager({
 *   openaiDailyBudget: 0.50,
 *   openaiPerRequestLimit: 0.005,
 * });
 *
 * const check = manager.canUseOpenAI(0.003);
 * if (check.allowed) {
 *   // ... make API call ...
 *   manager.trackOpenAIUsage(0.003, 1500, 'gpt-4o-mini');
 * }
 * ```
 */

import type { Logger } from "../types.js";
import { defaultLogger } from "../types.js";

// ============================================================================
// TYPES
// ============================================================================

export interface BudgetCheckResult {
  allowed: boolean;
  reason?: string;
  currentUsage: APIUsageStats;
  waitTimeMs?: number;
}

export interface APIUsageStats {
  service: string;
  requestsToday: number;
  requestsThisMonth: number;
  costToday: number;
  costThisMonth: number;
  lastRequestTime?: Date;
  budgetRemaining: number;
  quotaRemaining?: number;
}

export interface APIBudgetConfig {
  // OpenAI
  openaiDailyBudget: number; // USD
  openaiMonthlyBudget: number; // USD
  openaiPerRequestLimit: number; // USD
  openaiAlertThreshold: number; // 0-1

  // Generic external API rate limits
  externalAPIDailyQuota: number; // requests
  externalAPIRateLimit: number; // requests per second

  // Emergency stop
  emergencyStopEnabled: boolean;
}

export interface RateLimitState {
  tokens: number;
  lastRefill: number;
  capacity: number;
  refillRate: number; // tokens per millisecond
}

/** Callback for persisting usage data externally. */
export interface UsagePersistence {
  onUsageTracked?: (
    service: string,
    cost: number,
    tokens: number,
    model: string
  ) => void | Promise<void>;
  onBudgetAlert?: (service: string, percentageUsed: number) => void | Promise<void>;
  onEmergencyStop?: (service: string, reason: string) => void | Promise<void>;
}

// ============================================================================
// DEFAULT CONFIGURATION
// ============================================================================

const DEFAULT_CONFIG: APIBudgetConfig = {
  // OpenAI defaults tuned for MCP usage (< $0.005 per analysis)
  openaiDailyBudget: parseFloat(process.env.AI_DAILY_BUDGET ?? "0.50"),
  openaiMonthlyBudget: parseFloat(process.env.AI_MONTHLY_BUDGET ?? "10.00"),
  openaiPerRequestLimit: parseFloat(process.env.AI_PER_VIDEO_LIMIT ?? "0.01"),
  openaiAlertThreshold: parseFloat(process.env.AI_ALERT_THRESHOLD ?? "0.80"),

  // Generic external API defaults
  externalAPIDailyQuota: 10000,
  externalAPIRateLimit: 5, // 5 req/sec

  // Emergency stop
  emergencyStopEnabled: process.env.AI_EMERGENCY_STOP !== "false",
};

// ============================================================================
// IN-MEMORY USAGE TRACKER
// ============================================================================

interface UsageCounters {
  requestsToday: number;
  requestsThisMonth: number;
  costToday: number;
  costThisMonth: number;
  lastRequestTime?: Date;
  dayStart: number; // timestamp of day start
  monthStart: number; // timestamp of month start
}

function createUsageCounters(): UsageCounters {
  const now = new Date();
  const dayStart = new Date(now.getFullYear(), now.getMonth(), now.getDate()).getTime();
  const monthStart = new Date(now.getFullYear(), now.getMonth(), 1).getTime();

  return {
    requestsToday: 0,
    requestsThisMonth: 0,
    costToday: 0,
    costThisMonth: 0,
    dayStart,
    monthStart,
  };
}

/**
 * Auto-reset counters if the day/month has changed since last check.
 */
function maybeResetCounters(counters: UsageCounters): void {
  const now = new Date();
  const currentDayStart = new Date(
    now.getFullYear(),
    now.getMonth(),
    now.getDate()
  ).getTime();
  const currentMonthStart = new Date(
    now.getFullYear(),
    now.getMonth(),
    1
  ).getTime();

  if (currentDayStart > counters.dayStart) {
    counters.requestsToday = 0;
    counters.costToday = 0;
    counters.dayStart = currentDayStart;
  }

  if (currentMonthStart > counters.monthStart) {
    counters.requestsThisMonth = 0;
    counters.costThisMonth = 0;
    counters.monthStart = currentMonthStart;
  }
}

// ============================================================================
// API BUDGET MANAGER CLASS
// ============================================================================

export class APIBudgetManager {
  private config: APIBudgetConfig;
  private logger: Logger;
  private persistence?: UsagePersistence;
  private rateLimitStates: Map<string, RateLimitState> = new Map();
  private usageCounters: Map<string, UsageCounters> = new Map();

  constructor(
    config: Partial<APIBudgetConfig> = {},
    logger?: Logger,
    persistence?: UsagePersistence
  ) {
    this.config = { ...DEFAULT_CONFIG, ...config };
    this.logger = logger ?? defaultLogger;
    this.persistence = persistence;
    this.initializeRateLimiters();
  }

  // ==========================================================================
  // INITIALIZATION
  // ==========================================================================

  private initializeRateLimiters(): void {
    // Generic external API rate limiter
    this.rateLimitStates.set("external", {
      tokens: this.config.externalAPIRateLimit,
      lastRefill: Date.now(),
      capacity: this.config.externalAPIRateLimit,
      refillRate: this.config.externalAPIRateLimit / 1000,
    });
  }

  private getCounters(service: string): UsageCounters {
    let counters = this.usageCounters.get(service);
    if (!counters) {
      counters = createUsageCounters();
      this.usageCounters.set(service, counters);
    }
    maybeResetCounters(counters);
    return counters;
  }

  // ==========================================================================
  // OPENAI API BUDGET MANAGEMENT
  // ==========================================================================

  /**
   * Check if OpenAI API call is allowed within budget.
   */
  canUseOpenAI(estimatedCost: number): BudgetCheckResult {
    const counters = this.getCounters("openai");

    const usage: APIUsageStats = {
      service: "openai",
      requestsToday: counters.requestsToday,
      requestsThisMonth: counters.requestsThisMonth,
      costToday: counters.costToday,
      costThisMonth: counters.costThisMonth,
      lastRequestTime: counters.lastRequestTime,
      budgetRemaining: this.config.openaiDailyBudget - counters.costToday,
    };

    // Check per-request limit
    if (estimatedCost > this.config.openaiPerRequestLimit) {
      return {
        allowed: false,
        reason: `Request cost ($${estimatedCost.toFixed(4)}) exceeds per-request limit ($${this.config.openaiPerRequestLimit})`,
        currentUsage: usage,
      };
    }

    // Check daily budget
    if (counters.costToday + estimatedCost > this.config.openaiDailyBudget) {
      return {
        allowed: false,
        reason: `Daily budget exceeded ($${counters.costToday.toFixed(2)}/$${this.config.openaiDailyBudget})`,
        currentUsage: usage,
      };
    }

    // Check monthly budget
    if (
      counters.costThisMonth + estimatedCost >
      this.config.openaiMonthlyBudget
    ) {
      return {
        allowed: false,
        reason: `Monthly budget exceeded ($${counters.costThisMonth.toFixed(2)}/$${this.config.openaiMonthlyBudget})`,
        currentUsage: usage,
      };
    }

    // Check alert threshold
    const dailyPercentage =
      (counters.costToday + estimatedCost) / this.config.openaiDailyBudget;
    if (dailyPercentage >= this.config.openaiAlertThreshold) {
      this.logger.warn("OpenAI budget alert", {
        dailyPercentageUsed: parseFloat((dailyPercentage * 100).toFixed(1)),
      });
      void this.persistence?.onBudgetAlert?.("openai", dailyPercentage);
    }

    return {
      allowed: true,
      currentUsage: usage,
    };
  }

  /**
   * Track OpenAI API usage after a successful call.
   */
  trackOpenAIUsage(cost: number, tokens: number, model: string): void {
    const counters = this.getCounters("openai");
    counters.requestsToday++;
    counters.requestsThisMonth++;
    counters.costToday += cost;
    counters.costThisMonth += cost;
    counters.lastRequestTime = new Date();

    this.logger.info("OpenAI usage tracked", {
      cost: `$${cost.toFixed(4)}`,
      tokens,
      model,
    });

    void this.persistence?.onUsageTracked?.("openai", cost, tokens, model);
  }

  // ==========================================================================
  // GENERIC EXTERNAL API RATE LIMITING
  // ==========================================================================

  /**
   * Check if an external API call is allowed (rate limiting via token bucket).
   */
  canUseExternalAPI(serviceName: string): BudgetCheckResult {
    let state = this.rateLimitStates.get(serviceName);
    if (!state) {
      // Create a new rate limiter for unknown services using default config
      state = {
        tokens: this.config.externalAPIRateLimit,
        lastRefill: Date.now(),
        capacity: this.config.externalAPIRateLimit,
        refillRate: this.config.externalAPIRateLimit / 1000,
      };
      this.rateLimitStates.set(serviceName, state);
    }

    const counters = this.getCounters(serviceName);

    const usage: APIUsageStats = {
      service: serviceName,
      requestsToday: counters.requestsToday,
      requestsThisMonth: counters.requestsThisMonth,
      costToday: counters.costToday,
      costThisMonth: counters.costThisMonth,
      lastRequestTime: counters.lastRequestTime,
      budgetRemaining: this.config.externalAPIDailyQuota - counters.requestsToday,
      quotaRemaining: this.config.externalAPIDailyQuota - counters.requestsToday,
    };

    // Refill tokens based on time elapsed
    const now = Date.now();
    const elapsedMs = now - state.lastRefill;
    const tokensToAdd = elapsedMs * state.refillRate;
    state.tokens = Math.min(state.capacity, state.tokens + tokensToAdd);
    state.lastRefill = now;

    // Check if we have tokens available
    if (state.tokens < 1) {
      const waitTimeMs = Math.ceil((1 - state.tokens) / state.refillRate);
      return {
        allowed: false,
        reason: `${serviceName} rate limit exceeded. Wait ${waitTimeMs}ms`,
        currentUsage: usage,
        waitTimeMs,
      };
    }

    // Check daily quota
    if (counters.requestsToday >= this.config.externalAPIDailyQuota) {
      return {
        allowed: false,
        reason: `${serviceName} daily quota exceeded (${counters.requestsToday}/${this.config.externalAPIDailyQuota})`,
        currentUsage: usage,
      };
    }

    return {
      allowed: true,
      currentUsage: usage,
    };
  }

  /**
   * Consume an external API token (call AFTER successful API request).
   */
  trackExternalAPIUsage(serviceName: string, cost = 0): void {
    const state = this.rateLimitStates.get(serviceName);
    if (state) {
      state.tokens = Math.max(0, state.tokens - 1);
    }

    const counters = this.getCounters(serviceName);
    counters.requestsToday++;
    counters.requestsThisMonth++;
    counters.costToday += cost;
    counters.costThisMonth += cost;
    counters.lastRequestTime = new Date();
  }

  // ==========================================================================
  // AGGREGATE STATS & REPORTING
  // ==========================================================================

  /**
   * Get usage stats for all tracked services.
   */
  getAllUsageStats(): APIUsageStats[] {
    const stats: APIUsageStats[] = [];

    for (const [service, counters] of this.usageCounters.entries()) {
      maybeResetCounters(counters);

      const budget =
        service === "openai"
          ? this.config.openaiDailyBudget - counters.costToday
          : this.config.externalAPIDailyQuota - counters.requestsToday;

      stats.push({
        service,
        requestsToday: counters.requestsToday,
        requestsThisMonth: counters.requestsThisMonth,
        costToday: counters.costToday,
        costThisMonth: counters.costThisMonth,
        lastRequestTime: counters.lastRequestTime,
        budgetRemaining: budget,
        quotaRemaining:
          service === "openai"
            ? undefined
            : this.config.externalAPIDailyQuota - counters.requestsToday,
      });
    }

    return stats;
  }

  /**
   * Get human-readable usage report.
   */
  getUsageReport(): string {
    const stats = this.getAllUsageStats();
    const lines = ["=== API Usage Report ===", ""];

    for (const stat of stats) {
      lines.push(`${stat.service.toUpperCase()}:`);
      lines.push(`  Requests today: ${stat.requestsToday}`);
      lines.push(`  Cost today: $${stat.costToday.toFixed(4)}`);
      if (stat.quotaRemaining !== undefined) {
        lines.push(`  Quota remaining: ${stat.quotaRemaining}`);
      }
      lines.push("");
    }

    if (stats.length === 0) {
      lines.push("No API usage recorded yet.");
    }

    return lines.join("\n");
  }

  /**
   * Check if emergency stop should be triggered.
   */
  shouldEmergencyStop(): { stop: boolean; reason?: string } {
    if (!this.config.emergencyStopEnabled) {
      return { stop: false };
    }

    const counters = this.getCounters("openai");

    // Stop if daily budget exceeded
    if (counters.costToday >= this.config.openaiDailyBudget) {
      const reason = `OpenAI daily budget exceeded ($${counters.costToday.toFixed(2)}/$${this.config.openaiDailyBudget})`;
      void this.persistence?.onEmergencyStop?.("openai", reason);
      return { stop: true, reason };
    }

    // Stop if monthly budget exceeded
    if (counters.costThisMonth >= this.config.openaiMonthlyBudget) {
      const reason = `OpenAI monthly budget exceeded ($${counters.costThisMonth.toFixed(2)}/$${this.config.openaiMonthlyBudget})`;
      void this.persistence?.onEmergencyStop?.("openai", reason);
      return { stop: true, reason };
    }

    return { stop: false };
  }

  // ==========================================================================
  // UTILITIES
  // ==========================================================================

  /**
   * Estimate OpenAI cost for a transcript.
   * Uses GPT-4o-mini pricing by default.
   */
  estimateOpenAICost(transcript: string, _model = "gpt-4o-mini"): number {
    const tokens = Math.ceil(transcript.length / 4); // ~4 chars per token
    const inputCost = tokens * 0.00000015; // gpt-4o-mini: $0.150 per 1M input tokens
    const outputCost = 150 * 0.0000006; // ~150 output tokens * $0.600 per 1M output tokens
    return inputCost + outputCost;
  }

  /**
   * Reset daily counters.
   */
  resetDailyCounters(): void {
    for (const counters of this.usageCounters.values()) {
      counters.requestsToday = 0;
      counters.costToday = 0;
      counters.dayStart = Date.now();
    }
    this.logger.info("Daily counters reset");
  }

  /**
   * Reset monthly counters.
   */
  resetMonthlyCounters(): void {
    for (const counters of this.usageCounters.values()) {
      counters.requestsThisMonth = 0;
      counters.costThisMonth = 0;
      counters.monthStart = Date.now();
    }
    this.logger.info("Monthly counters reset");
  }

  /**
   * Reset all counters and rate limiters.
   */
  resetAll(): void {
    this.usageCounters.clear();
    this.rateLimitStates.clear();
    this.initializeRateLimiters();
    this.logger.info("All budget counters and rate limiters reset");
  }
}

