export type PromotionType =
  | "sale"
  | "flash-deal"
  | "seasonal"
  | "holiday"
  | "clearance"
  | "ethnobotanical";

export type PromotionRegion = "UK" | "US" | "EU" | "AU" | "GLOBAL";

export interface PromotionData {
