/**
 * Build PromotionData from a default template for a given year.
 */
export function buildPromotionFromTemplate(
  template: DefaultPromotionTemplate,
  year: number,
): CreatePromotionInput {
  const startDate = new Date(year, template.monthStart, template.dayStart);
  const endDate = new Date(
    year,
    template.monthEnd,
    template.dayEnd,
    23,
    59,
    59,
  );

  // Handle promotions that span year boundary
  if (template.monthEnd < template.monthStart) {
    endDate.setFullYear(year + 1);
  }

  return {
    title: template.title,
    description: template.description,
    type: template.type,
    region: template.region,
    season: template.season,
    badgeText: template.badgeText,
    badgeColor: template.badgeColor,
    categories: template.categories,
    keywords: template.keywords,
    startDate,
    endDate,
    featured: template.featured,
  };
}

/**
 * Unit tests for pipeline-orchestrator.ts pure utility functions.
 *
 * Covers: timestampToSeconds, buildTimestampUrl
 * Both are module-level pure functions — no mocks needed.
 */

import { describe, it, expect } from "vitest";
import {
  timestampToSeconds,
  buildTimestampUrl,
} from "../../pipeline-orchestrator.js";

// ============================================================================
// timestampToSeconds
// ============================================================================

describe("timestampToSeconds", () => {
  it("converts MM:SS to seconds", () => {
    expect(timestampToSeconds("1:30")).toBe(90);
  });

  it("converts HH:MM:SS to seconds", () => {
    expect(timestampToSeconds("1:00:00")).toBe(3600);
  });

  it("handles 0:00 → 0", () => {
    expect(timestampToSeconds("0:00")).toBe(0);
  });

  it("handles multi-hour HH:MM:SS", () => {
    expect(timestampToSeconds("2:15:45")).toBe(2 * 3600 + 15 * 60 + 45);
  });

  it("handles zero-padded MM:SS", () => {
    expect(timestampToSeconds("0:45")).toBe(45);
  });

  it("returns 0 for empty string", () => {
    expect(timestampToSeconds("")).toBe(0);
  });

  it("returns 0 for malformed string (NaN parts)", () => {
    expect(timestampToSeconds("abc:def")).toBe(0);
  });

  it("returns 0 for single-part string (no colon)", () => {
    expect(timestampToSeconds("120")).toBe(0);
  });

  it("returns 0 for 4-part string (too many colons)", () => {
    expect(timestampToSeconds("1:2:3:4")).toBe(0);
  });
});

// ============================================================================
// buildTimestampUrl
// ============================================================================

describe("buildTimestampUrl", () => {
  it("builds URL from MM:SS timestamp", () => {
    expect(buildTimestampUrl("dQw4w9WgXcQ", "1:30")).toBe(
      "https://youtu.be/dQw4w9WgXcQ?t=90",
    );
  });

  it("builds URL from HH:MM:SS timestamp", () => {
    expect(buildTimestampUrl("abc123", "1:00:00")).toBe(
      "https://youtu.be/abc123?t=3600",
    );
  });

  it("returns undefined for empty timestamp", () => {
    expect(buildTimestampUrl("vid123", "")).toBeUndefined();
  });

  it("returns URL with t=0 for malformed timestamp", () => {
    expect(buildTimestampUrl("vid123", "bad:ts")).toBe(
      "https://youtu.be/vid123?t=0",
    );
  });

  it("uses the exact videoId in the URL", () => {
    const url = buildTimestampUrl("test-video-id_v2", "0:30");
    expect(url).toContain("test-video-id_v2");
  });
});

/**
 * Unit tests for the transcript parser module.
 *
 * Tests:
 * - YouTube ID extraction from various URL formats
 * - Timestamp formatting
 * - ISO 8601 duration parsing
 * - (XML/JSON3 parsers are internal but tested via integration)
 */

import { describe, it, expect } from "vitest";
import {
  extractYouTubeId,
  formatSeconds,
  parseDuration,
} from "../../transcript/transcript-parser.js";
import { YOUTUBE_URL_TEST_CASES } from "../fixtures/sample-transcript.js";

describe("Transcript Parser", () => {
  describe("extractYouTubeId", () => {
    for (const { url, expected } of YOUTUBE_URL_TEST_CASES) {
      it(`extracts "${expected}" from "${url}"`, () => {
        expect(extractYouTubeId(url)).toBe(expected);
      });
    }

    it("extracts ID from URL with extra query params", () => {
      expect(
        extractYouTubeId(
          "https://www.youtube.com/watch?v=dQw4w9WgXcQ&t=120&list=PLabc",
        ),
      ).toBe("dQw4w9WgXcQ");
    });

    it("returns null for non-YouTube URLs", () => {
      expect(extractYouTubeId("https://vimeo.com/123456")).toBeNull();
    });

    it("returns null for short IDs (not 11 chars)", () => {
      expect(extractYouTubeId("abc")).toBeNull();
    });
  });

  describe("formatSeconds", () => {
    it("formats seconds under 1 hour as MM:SS", () => {
      expect(formatSeconds(0)).toBe("00:00");
      expect(formatSeconds(5)).toBe("00:05");
      expect(formatSeconds(65)).toBe("01:05");
      expect(formatSeconds(3599)).toBe("59:59");
    });

    it("formats seconds over 1 hour as HH:MM:SS", () => {
      expect(formatSeconds(3600)).toBe("01:00:00");
      expect(formatSeconds(3661)).toBe("01:01:01");
      expect(formatSeconds(7200)).toBe("02:00:00");
    });

    it("handles fractional seconds by flooring", () => {
      expect(formatSeconds(65.7)).toBe("01:05");
    });
  });

  describe("parseDuration", () => {
    it("parses ISO 8601 durations", () => {
      expect(parseDuration("PT15M51S")).toBe(951);
      expect(parseDuration("PT1H2M3S")).toBe(3723);
      expect(parseDuration("PT30S")).toBe(30);
      expect(parseDuration("PT10M")).toBe(600);
      expect(parseDuration("PT2H")).toBe(7200);
    });

    it("returns 0 for invalid duration strings", () => {
      expect(parseDuration("invalid")).toBe(0);
      expect(parseDuration("")).toBe(0);
    });
  });
});

/**
 * Unit tests for PlantDictionary — lookup, search, and size methods
 * across Latin name, common name, synonym, and genus indices.
 */

import { describe, it, expect, beforeAll } from "vitest";
import type { PlantDictionary } from "../../types.js";
import { createPlantDictionary, createEmptyDictionary } from "../../ner/plant-dictionary.js";
import { SAMPLE_PLANT_ENTRIES } from "../fixtures/sample-plant-dictionary.js";

describe("PlantDictionary", () => {
  let dict: PlantDictionary;

  beforeAll(() => {
    dict = createPlantDictionary(SAMPLE_PLANT_ENTRIES);
  });

  it("size() returns correct entry count", () => {
    expect(dict.size()).toBe(SAMPLE_PLANT_ENTRIES.length);
  });

  it("getAll() returns all entries", () => {
    expect(dict.getAll()).toHaveLength(SAMPLE_PLANT_ENTRIES.length);
  });

  describe("findByLatinName", () => {
    it("finds entry by exact Latin name", () => {
      expect(dict.findByLatinName("Helenium autumnale")?.latinName).toBe("Helenium autumnale");
    });

    it("is case-insensitive", () => {
      expect(dict.findByLatinName("LAVANDULA ANGUSTIFOLIA")?.latinName).toBe("Lavandula angustifolia");
    });

    it("returns undefined for unknown Latin name", () => {
      expect(dict.findByLatinName("Fake species novum")).toBeUndefined();
    });
  });

  describe("findByName", () => {
    it("finds by Latin name", () => {
      expect(dict.findByName("Rudbeckia fulgida")?.latinName).toBe("Rudbeckia fulgida");
    });

    it("finds by common name", () => {
      expect(dict.findByName("English Lavender")?.latinName).toBe("Lavandula angustifolia");
    });

    it("finds by synonym", () => {
      expect(dict.findByName("Lavandula officinalis")?.latinName).toBe("Lavandula angustifolia");
    });

    it("returns undefined for unknown name", () => {
      expect(dict.findByName("Toyota Corolla")).toBeUndefined();
    });
  });

  describe("findByCommonName", () => {
    it("returns entries matching common name", () => {
      const results = dict.findByCommonName("Sneezeweed");
      expect(results).toHaveLength(1);
      expect(results[0]?.latinName).toBe("Helenium autumnale");
    });

    it("returns empty array for unknown common name", () => {
      expect(dict.findByCommonName("Invisible Plant")).toHaveLength(0);
    });
  });

  describe("findByGenus", () => {
    it("returns all plants of the specified genus", () => {
      const results = dict.findByGenus("Echinacea");
      expect(results.length).toBeGreaterThan(0);
      expect(results.every((e) => e.genus === "Echinacea")).toBe(true);
    });

    it("returns empty array for unknown genus", () => {
      expect(dict.findByGenus("Ficus")).toHaveLength(0);
    });
  });

  describe("search", () => {
    it("matches partial Latin name", () => {
      expect(dict.search("Miscanthus").some((e) => e.latinName === "Miscanthus sinensis")).toBe(true);
    });

    it("matches partial common name across multiple entries", () => {
      expect(dict.search("Coneflower").length).toBeGreaterThanOrEqual(2);
    });
  });

  describe("createEmptyDictionary", () => {
    it("size() is 0 and getAll() is empty", () => {
      const empty = createEmptyDictionary();
      expect(empty.size()).toBe(0);
      expect(empty.getAll()).toHaveLength(0);
    });
  });
});

import { describe, it, expect, beforeAll } from "vitest";
import { MultiCategoryPreprocessor } from "../../transcript/multi-category-preprocessor.js";

describe("MultiCategoryPreprocessor", () => {
  let preprocessor: MultiCategoryPreprocessor;

  beforeAll(async () => {
    preprocessor = new MultiCategoryPreprocessor();
    await preprocessor.initialize();
  });

  describe("detectCategories", () => {
    it("returns empty array for empty transcript", () => {
      expect(preprocessor.detectCategories("")).toEqual([]);
    });

    it("returns empty when fewer than 3 keywords match in any category", () => {
      // Only 2 TOOL keywords — below threshold of 3
      expect(preprocessor.detectCategories("spade trowel")).toEqual([]);
    });

    it("detects TOOL when exactly 3 keywords present", () => {
      const result = preprocessor.detectCategories("spade fork trowel");
      expect(result).toContain("TOOL");
    });

    it("detects PLANT when 3+ keywords present", () => {
      const result = preprocessor.detectCategories("lavender rose tulip");
      expect(result).toContain("PLANT");
    });

    it("detects MATERIAL when 3+ keywords present", () => {
      const result = preprocessor.detectCategories("compost mulch fertilizer");
      expect(result).toContain("MATERIAL");
    });

    it("detects SEED when 3+ keywords present", () => {
      const result = preprocessor.detectCategories("seed packet germination sowing");
      expect(result).toContain("SEED");
    });

    it("detects STRUCTURE when 3+ keywords present", () => {
      const result = preprocessor.detectCategories("greenhouse planter cold frame container");
      expect(result).toContain("STRUCTURE");
    });

    it("detects BOOK when 3+ keywords present", () => {
      const result = preprocessor.detectCategories("gardening book guide reference manual");
      expect(result).toContain("BOOK");
    });

    it("detects multiple categories simultaneously", () => {
      const transcript =
        "spade fork trowel lavender rose tulip compost mulch fertilizer";
      const result = preprocessor.detectCategories(transcript);
      expect(result).toContain("TOOL");
      expect(result).toContain("PLANT");
      expect(result).toContain("MATERIAL");
    });

    it("is case-insensitive", () => {
      const result = preprocessor.detectCategories("SPADE FORK TROWEL");
      expect(result).toContain("TOOL");
    });

    it("handles mixed case", () => {
      const result = preprocessor.detectCategories("Compost Mulch Fertilizer Soil");
      expect(result).toContain("MATERIAL");
    });

    it("returns no duplicate categories", () => {
      const result = preprocessor.detectCategories("spade fork trowel");
      expect(result).toHaveLength(new Set(result).size);
    });

    it("does not detect TOOL when only 2 keywords match", () => {
      const result = preprocessor.detectCategories("spade trowel");
      expect(result).not.toContain("TOOL");
    });

    it("returns empty array for unrelated text", () => {
      const result = preprocessor.detectCategories("hello world the weather is nice today");
      expect(result).toHaveLength(0);
    });

    it("returns an array (not null or undefined)", () => {
      const result = preprocessor.detectCategories("random text");
      expect(Array.isArray(result)).toBe(true);
    });
  });
});
